   $ex${"titre":"Une maison sur pilotis dans le Grand Nord","competence":"observer-schema","situation":"Dans un village du Grand Nord canadien, le sol est gelé presque toute l’année. Pourtant, des familles y construisent leur maison. Regarde comment.","documents":[{"id":"maison","type":"schema","titre":"Une maison du Grand Nord, vue en coupe","largeur":340,"hauteur":245,"source":"Schéma simplifié écrit pour l’exercice.","elements":[{"forme":"rect","x":20,"y":130,"l":300,"h":30,"teinte":"brun","motif":"clair","id":"z1","zone":true},{"forme":"rect","x":20,"y":160,"l":300,"h":70,"teinte":"bleu","motif":"hachures","id":"z2","zone":true},{"forme":"texte","x":28,"y":150,"texte":"Dégèle l’été","taille":"petit","ancre":"debut"},{"forme":"texte","x":28,"y":193,"texte":"Sol gelé","taille":"petit","ancre":"debut"},{"forme":"texte","x":28,"y":207,"texte":"toute l’année","taille":"petit","ancre":"debut"},{"forme":"chemin","d":"M145 112 h8 v88 h-8 z M190 112 h8 v88 h-8 z M235 112 h8 v88 h-8 z M280 112 h8 v88 h-8 z","teinte":"brun","motif":"plein","id":"z3","zone":true},{"forme":"rect","x":130,"y":60,"l":180,"h":52,"teinte":"jaune","motif":"clair","id":"z4","zone":true},{"forme":"polygone","points":[[120,60],[220,25],[320,60]],"teinte":"corail","motif":"plein","id":"z5","zone":true},{"forme":"rect","x":212,"y":82,"l":24,"h":30,"teinte":"brun","motif":"plein"},{"forme":"rect","x":145,"y":75,"l":28,"h":22,"teinte":"ciel","motif":"plein"},{"forme":"rect","x":270,"y":75,"l":28,"h":22,"teinte":"ciel","motif":"plein"},{"forme":"rect","x":262,"y":22,"l":14,"h":32,"teinte":"gris","motif":"plein"},{"forme":"emoji","x":60,"y":90,"emoji":"❄️","taille":30},{"forme":"etiquette","x":70,"y":125,"texte":"Vide d’air","vers":[135,121]}]}],"questions":[{"enonce":"Touche la couche qui reste **gelée toute l’année** : le permafrost.","aide":"C’est le sol le plus profond, avec des hachures.","type":"zone","document":"maison","multiple":false},{"enonce":"Touche ce qui **soulève** la maison au-dessus du sol : les pieux.","aide":"Ce sont quatre piliers enfoncés dans le sol.","type":"zone","document":"maison","multiple":false},{"enonce":"Touche la couche du sol qui **dégèle l’été**.","aide":"Elle se trouve juste sous la maison, au-dessus du sol gelé.","type":"zone","document":"maison","multiple":false},{"enonce":"Pourquoi laisser un vide d’air sous la maison ?","aide":"Une maison chauffée dégage de la chaleur.","type":"choix","options":[{"id":"a","texte":"Pour y garer des voitures"},{"id":"b","texte":"Pour que sa chaleur ne fasse pas dégeler le sol"},{"id":"c","texte":"Pour la rendre plus haute que les autres"},{"id":"d","texte":"Pour faire entrer l’eau"}],"multiple":false}]}$ex$::jsonb,
