us de médecin dans le village.","type":"zone","document":"temoins","multiple":false,"portee":[2]},{"enonce":"Quel indice du tableau montre que Aubépine est périurbaine ?","aide":"Regarde la dernière colonne.","type":"choix","options":[{"id":"a","texte":"Elle n’a aucune route pour en sortir"},{"id":"b","texte":"80 % de ses actifs travaillent ailleurs"},{"id":"c","texte":"Elle a perdu une partie de ses habitants"},{"id":"d","texte":"Elle ne compte que 20 actifs en tout"}],"multiple":false}]}$ex$::jsonb,
