  ('e5de074a-b0ba-58c1-825e-eeade04e8a46'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le Niger, le Japon : deux pays, deux tendances","competence":"raisonner","situation":"Pour savoir si la population d’un pays augmente ou diminue, on compare les naissances et les décès, toujours pour 1 000 habitants. Calcule l’accroissement naturel de deux pays très différents.","documents":[{"id":"taux","type":"tableau","titre":"Naissances et décès pour 1 000 habitants","source":"ONU, vers 2022, chiffres arrondis.","colonnes":["Pays","Naissances (pour 1 000)","Décès (pour 1 000)"],"lignes":[["Niger","46","10"],["Japon","6","13"],["France","11","10"]],"enteteLignes":true},{"id":"transition","type":"graphique","forme":"courbe","titre":"Les quatre temps de la transition démographique","source":"Schéma illustratif, valeurs imaginées pour montrer l’idée.","categories":["Ancien régime","Début de transition","Fin de transition","Régime moderne"],"series":[{"nom":"Naissances","valeurs":[40,40,30,12],"teinte":"violet"},{"nom":"Décès","valeurs":[38,20,12,10],"teinte":"corail"}],"axeY":{"titre":"Pour 1 000 habitants","min":0,"max":45,"pas":5}}],"questions":[{"enonce":"Calcule l’**accroissement naturel** du Niger : naissances − décès. Combien pour 1 000 habitants ?","aide":"46 − 10.","type":"nombre","unite":"‰"},{"enonce":"Au Japon, il y a plus de décès que de naissances. De combien la population baisse-t-elle pour 1 000 habitants ? Donne un nombre positif.","aide":"13 − 6.","type":"nombre","unite":"‰"},{"enonce":"Touche le moment où l’écart entre naissances et décès est **le plus grand** : la population explose.","aide":"Cherche où les deux courbes sont les plus éloignées.","type":"zone","document":"transition","multiple":false},{"enonce":"Pourquoi le Niger et le Japon n’ont-ils pas la même évolution ?","aide":"Relis le Doc 2 : quatre étapes.","type":"choix","options":[{"id":"a","texte":"Les chiffres sont toujours identiques partout"},{"id":"b","texte":"Le Niger n’a pas du tout de naissances"},{"id":"c","texte":"Ils sont à des stades différents de la transition"},{"id":"d","texte":"Le Japon a beaucoup plus de forêts que lui"}],"multiple":false}]}$ex$::jsonb,
