   $ex${"titre":"Les billes de Théo","competence":"calculer","situation":"Théo a 24 billes. Il en donne les **{{3/4}}** à sa sœur. Ses amis Sarah et Eliott font aussi des dons : on les compare dans le tableau.","documents":[{"id":"bande","type":"schema","titre":"La collection de Théo, partagée en 4 parts égales","largeur":320,"hauteur":140,"elements":[{"forme":"ligne","de":[40,40],"a":[280,40],"fleche":"deux","teinte":"encre"},{"forme":"texte","x":160,"y":28,"texte":"24 billes","ancre":"milieu","gras":true},{"forme":"rect","x":40,"y":60,"l":60,"h":50,"teinte":"vert","motif":"clair","id":"z1"},{"forme":"rect","x":100,"y":60,"l":60,"h":50,"teinte":"vert","motif":"clair","id":"z2"},{"forme":"rect","x":160,"y":60,"l":60,"h":50,"teinte":"vert","motif":"clair","id":"z3"},{"forme":"rect","x":220,"y":60,"l":60,"h":50,"teinte":"vert","motif":"clair","id":"z4"}]},{"id":"dons","type":"tableau","titre":"Les dons de billes","colonnes":["Ami","Billes","Part donnée"],"lignes":[["Théo",24,"{{3/4}}"],["Sarah",40,"{{2/5}}"],["Eliott",30,"{{1/3}}"]],"enteteLignes":true,"source":"Chiffres inventés pour l’exercice"}],"questions":[{"enonce":"Combien de billes y a-t-il dans **une** part de la bande ?","aide":"La bande de 24 billes est partagée en 4 parts égales.","type":"nombre","unite":"billes"},{"enonce":"Combien de billes Théo donne-t-il à sa sœur (les {{3/4}} de 24) ?","aide":"Les {{3/4}}, c’est 3 parts de la bande.","type":"nombre","unite":"billes"},{"enonce":"Quelle fraction de ses billes Théo garde-t-il ?","aide":"La bande a 4 parts, il en donne 3.","type":"choix","options":[{"id":"a","texte":"{{1/4}}"},{"id":"b","texte":"{{3/4}}"},{"id":"c","texte":"{{1/3}}"},{"id":"d","texte":"{{4/3}}"}],"multiple":false},{"enonce":"Sarah a 40 billes et en donne les {{2/5}}. Combien en donne-t-elle ?","aide":"Divise 40 par 5, puis multiplie par 2.","type":"nombre","unite":"billes"},{"enonce":"Qui donne le **plus** de billes ? Touche son prénom.","aide":"Calcule aussi ce que donne Eliott : les {{1/3}} de 30.","type":"zone","document":"dons","multiple":false}]}$ex$::jsonb,
