elle aire reste-t-il à peindre ?","aide":"Calcule l’aire de chaque ouverture, additionne-les, puis retire-les de 24 m².","type":"choix","options":[{"id":"a","texte":"20,5 m²"},{"id":"b","texte":"24 m²"},{"id":"c","texte":"27,5 m²"},{"id":"d","texte":"22 m²"}],"multiple":false},{"enonce":"Un pot couvre 5 m² et coûte 14 €. Louis n’achète que des pots entiers. Combien dépense-t-il ?","aide":"Combien de pots faut-il pour couvrir au moins 20,5 m² ? 20,5 ÷ 5 donne un nombre avec une virgule.","type":"nombre","unite":"€"}]}$ex$::jsonb,
