   $ex$[{"cle":{"type":"zone","ids":["z7","z8"]},"explication":"Les nombres strictement supérieurs à 6 sont **7 et 8**."},{"cle":{"type":"nombre","valeur":8,"tolerance":0},"affichage":"8","explication":"Chaque secteur est une issue : il y en a **8**."},{"cle":{"type":"nombre","valeur":0.25,"tolerance":0},"affichage":"0,25","explication":"Il y a 2 cas favorables (7 et 8) sur 8 cas possibles : P = {{2/8}} = {{1/4}} = **0,25**."}]$ex$::jsonb),
  ('7c0536c3-5d68-5cfc-b877-7064e51a0fcf'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le sac de billes de Yanis","competence":"resoudre","situation":"Yanis a un sac opaque avec douze billes identiques au toucher. Elles se distinguent seulement par leur motif : unies, rayées ou à points. Il en tire une sans regarder.","documents":[{"id":"sac","type":"schema","titre":"Le contenu du sac","source":"Sac dessiné pour l’exercice","largeur":320,"hauteur":290,"elements":[{"forme":"rect","x":40,"y":40,"l":240,"h":175,"arrondi":28,"teinte":"brun","motif":"clair"},{"forme":"cercle","cx":90,"cy":80,"r":18,"teinte":"encre","motif":"plein","id":"z1","zone":true},{"forme":"cercle","cx":137,"cy":80,"r":18,"teinte":"encre","motif":"hachures","id":"z2","zone":true},{"forme":"cercle","cx":184,"cy":80,"r":18,"teinte":"encre","motif":"points","id":"z3","zone":true},{"forme":"cercle","cx":231,"cy":80,"r":18,"teinte":"encre","motif":"plein","id":"z4","zone":true},{"forme":"cercle","cx":90,"cy":127,"r":18,"teinte":"encre","motif":"hachures","id":"z5","zone":true},{"forme":"cercle","cx":137,"cy":127,"r":18,"teinte":"encre","motif":"plein","id":"z6","zone":true},{"forme":"cercle","cx":184,"cy":127,"r":18,"teinte":"encre","motif":"plein","id":"z7","zone":true},{"forme":"cercle","cx":231,"cy":127,"r":18,"teinte":"encre","motif":"points","id":"z8","zone":true},{"forme":"cercle","cx":90,"cy":174,"r":18,"teinte":"encre","motif":"points","id":"z9","zone":true},{"forme":"cercle","cx":137,"cy":174,"r":18,"teinte":"encre","motif":"hachures","id":"z10","zone":true},{"forme":"cercle","cx":184,"cy":174,"r":18,"teinte":"encre","motif":"plein","id":"z11","zone":true},{"forme":"cercle","cx":231,"cy":174,"r":18,"teinte":"encre","motif":"hachures","id":"z12","zone":true},{"forme":"cercle","cx":70,"cy":258,"r":12,"teinte":"encre","motif":"plein"},{"forme":"texte","x":88,"y":263,"texte":"unie","taille":"petit","ancre":"debut"},{"forme":"cercle","cx":150,"cy":258,"r":12,"teinte":"encre","motif":"hachures"},{"forme":"texte","x":168,"y":263,"texte":"rayée","taille":"petit","ancre":"debut"},{"forme":"cercle","cx":235,"cy":258,"r":12,"teinte":"encre","motif":"points"},{"forme":"texte","x":253,"y":263,"texte":"à points","taille":"petit","ancre":"debut"}]}],"questions":[{"enonce":"Touche **toutes** les billes à points.","aide":"Regarde la légende sous le sac pour reconnaître le motif « à points ».","type":"zone","document":"sac","multiple":true},{"enonce":"Quelle est la probabilité de tirer une bille unie ? (une fraction, ou un décimal arrondi au centième)","aide":"Compte les billes unies, puis divise par le nombre total de billes.","type":"nombre"},{"enonce":"Quelle est la probabilité de **ne pas** tirer une bille à points ? (Une fraction ou un décimal.)","aide":"Cet événement est le contraire de « tirer une bille à points » : leurs probabilités font 1 à deux.","type":"nombre"},{"enonce":"Yanis ajoute dans le sac 6 billes à points. Quelle est maintenant la probabilité de tirer une bille à points ? (Une fraction ou un décimal.)","aide":"Le nombre total de billes a changé, et le nombre de billes à points aussi.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3","z8","z9"]},"explication":"Il y a **3 billes à points** sur 12."},{"cle":{"type":"nombre","valeur":0.4166666666666667,"tolerance":0.005},"affichage":"0,4167","explication":"5 billes unies sur 12 billes au total : P = **{{5/12}}**, soit environ 0,42."},{"cle":{"type":"nombre","valeur":0.75,"tolerance":0},"affichage":"0,75","explication":"9 billes sur 12 ne sont pas à points : P = {{9/12}} = {{3/4}} = **0,75**. Autre méthode : 1 − {{3/12}} = 0,75."},{"cle":{"type":"nombre","valeur":0.5,"tolerance":0},"affichage":"0,5","explication":"Il y a maintenant 3 + 6 = 9 billes à points sur 12 + 6 = 18 : P = {{9/18}} = {{1/2}} = **0,5**."}]$ex$::jsonb),
  ('7c0536c3-5d68-5cfc-b877-7064e51a0fcf'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Pile ou face au club de maths","competence":"raisonner","situation":"Au club de maths, Ilan et Chloé lancent une pièce équilibrée. Ils notent la fréquence des « pile » pour 10, 100 puis 1 000 lancers, puis discutent après une série de cinq « pile » à la suite.","documents":[{"id":"lancers","type":"tableau","titre":"Les lancers du club","source":"Résultats imaginés pour l’exercice","colonnes":["Lancers","Nombre de « pile »","Fréquence de « pile »"],"lignes":[[10,7,"0,7"],[100,56,"?"],[1000,507,"0,507"]],"enteteLignes":false},{"id":"dial","type":"dialogue","modele":"bulles","participants":[{"nom":"Ilan","emoji":"👦","cote":"gauche"},{"nom":"Chloé","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Ilan","texte":"Cinq pile à la suite ! Au prochain lancer, face a plus de chances de sortir."},{"qui":"Chloé","texte":"Je ne suis pas d’accord avec toi."}]}],"questions":[{"enonce":"Quelle est la probabilité d’obtenir « pile » au sixième lancer ?","aide":"Les lancers précédents changent-ils la pièce ?","type":"choix","options":[{"id":"a","texte":"Plus de {{1/2}}, car « pile » est en série"},{"id":"b","texte":"{{1/2}}, comme à chaque lancer : la pièce n’a pas de mémoire"},{"id":"c","texte":"On ne peut pas le savoir sans refaire le tirage"},{"id":"d","texte":"Moins de {{1/2}}, puisque « pile » est déjà sorti cinq fois"}],"multiple":false},{"enonce":"Quelle est la fréquence de « pile » pour 100 lancers (la case « ? ») ? (Un décimal.)","aide":"Fréquence = nombre de « pile » ÷ nombre de lancers.","type":"nombre"},{"enonce":"Que constate-t-on quand le nombre de lancers augmente (10, 100, puis 1 000) ?","aide":"Compare 0,7, 0,56 et 0,507 avec 0,5.","type":"choix","options":[{"id":"a","texte":"La fréquence s’éloigne de plus en plus de la valeur 0,5"},{"id":"b","texte":"La fréquence se rapproche de 0,5, la probabilité de « pile »"},{"id":"c","texte":"La fréquence ne change jamais, quel que soit le nombre"},{"id":"d","texte":"La fréquence finit par devenir exactement égale à 1"}],"multiple":false},{"enonce":"Range chaque événement : certain, impossible, ou ni l’un ni l’autre ?","aide":"Certain : probabilité 1. Impossible : probabilité 0.","type":"categories","categories":[{"id":"c0","texte":"Certain"},{"id":"c1","texte":"Impossible"},{"id":"c2","texte":"Ni l’un ni l’autre"}],"items":[{"id":"i0","texte":"Obtenir un 6 avec un dé à six faces"},{"id":"i1","texte":"Obtenir « pile » ou « face » avec une pièce"},{"id":"i2","texte":"Obtenir 7 avec un dé à six faces"},{"id":"i3","texte":"Obtenir un nombre inférieur à 7 avec un dé à six faces"},{"id":"i4","texte":"Tirer une bille unie dans un sac qui ne contient que des billes rayées"}]},{"enonce":"On lance un dé à six faces. Quelle est la probabilité de **ne pas** obtenir 6 ? (Une fraction, ou un décimal arrondi au centième)","aide":"C’est l’événement contraire de « obtenir 6 » : la somme des deux probabilités vaut 1.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["b"]},"explication":"Le hasard n’a pas de dette : chaque lancer a **une chance sur deux** de donner pile, quel que soit le passé."},{"cle":{"type":"nombre","valeur":0.56,"tolerance":0},"affichage":"0,56","explication":"56 ÷ 100 = **0,56**."},{"cle":{"type":"choix","ids":["b"]},"explication":"0,7 → 0,56 → 0,507 : plus on répète l’expérience, plus la fréquence **se rapproche** de la probabilité, 0,5."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c0","i2":"c1","i3":"c0","i4":"c1"}},"explication":"Un événement **certain** a pour probabilité 1, un événement **impossible** 0 ; obtenir un 6 a une chance sur six."},{"cle":{"type":"nombre","valeur":0.8333333333333334,"tolerance":0.005},"affichage":"0,8333","explication":"P(6) = {{1/6}}, donc P(pas 6) = 1 − {{1/6}} = **{{5/6}}**, soit environ 0,83."}]$ex$::jsonb),
  ('60cda20a-9d42-520c-8531-4653aa8a1cff'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le robot du gymnase","competence":"se-reperer-espace","situation":"Au gymnase, un petit robot se déplace sur un quadrillage de 1 m de côté. On lui donne l’instruction « aller à (x ; y) » : x est l’abscisse, y est l’ordonnée. Cinq plots sont posés sur le sol.","documents":[{"id":"sol","type":"figure","titre":"Le sol du gymnase","source":"Plan dessiné pour l’exercice, 1 carreau = 1 m","cadre":{"xmin":0,"xmax":7,"ymin":0,"ymax":6},"quadrillage":true,"axes":true,"points":[{"id":"A","x":1,"y":4,"position":"no"},{"id":"B","x":3,"y":2,"position":"se"},{"id":"F","x":2,"y":3,"position":"no"},{"id":"C","x":5,"y":5,"position":"ne"},{"id":"D","x":4,"y":1,"position":"se"}]}],"questions":[{"enonce":"Le robot reçoit l’instruction « aller à (3 ; 2) ». Touche le plot où il s’arrête.","aide":"Pars de l’origine : d’abord 3 vers la droite (abscisse), puis 2 vers le haut (ordonnée).","type":"zone","document":"sol","multiple":false},{"enonce":"Quelle est l’ordonnée du plot A ?","aide":"L’ordonnée se lit sur l’axe vertical.","type":"nombre"},{"enonce":"Complète la règle.","aide":"C’est la coordonnée horizontale.","type":"trous","segments":["Dans un couple de coordonnées, l’",0," s’écrit toujours en premier."],"banque":["altitude","abscisse","ordonnée","origine"]}]}$ex$::jsonb,
